<?php $title='Notificaciones'; ?><h1 class="title">Notificaciones</h1><?php if(!$notifications): ?><div class="notification is-light">Aún no tienes notificaciones.</div><?php else: ?><div class="box"><?php foreach($notifications as $n): ?><article class="media py-3"><div class="media-left"><span class="icon is-large has-text-primary">🔔</span></div><div class="media-content"><p><strong><?= e($n['title']) ?></strong></p><p><?= e($n['message']) ?></p><small>Canal: <?= e($n['channel']) ?> · Estado: <?= e($n['status']) ?> · <?= e($n['created_at']) ?></small></div></article><?php endforeach; ?></div><?php endif; ?>
